package forth

import (
	"errors"
	"strconv"
	"strings"
)

// op is a single executable step: a built-in word, a user-defined word,
// or a closure that pushes a number.
type op func(*forth) error

type forth struct {
	stack []int
	words map[string]op
}

func Forth(input []string) ([]int, error) {
	f := newForth()
	for _, line := range input {
		if err := f.evalLine(line); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

func newForth() *forth {
	return &forth{
		words: map[string]op{
			"+":  binOp(func(a, b int) (int, error) { return a + b, nil }),
			"-":  binOp(func(a, b int) (int, error) { return a - b, nil }),
			"*":  binOp(func(a, b int) (int, error) { return a * b, nil }),
			"/": binOp(func(a, b int) (int, error) {
				if b == 0 {
					return 0, errors.New("divide by zero")
				}
				return a / b, nil
			}),
			"dup": func(f *forth) error {
				if len(f.stack) < 1 {
					return errors.New("empty stack")
				}
				f.stack = append(f.stack, f.stack[len(f.stack)-1])
				return nil
			},
			"drop": func(f *forth) error {
				if len(f.stack) < 1 {
					return errors.New("empty stack")
				}
				f.stack = f.stack[:len(f.stack)-1]
				return nil
			},
			"swap": func(f *forth) error {
				if len(f.stack) < 2 {
					return stackError(len(f.stack))
				}
				n := len(f.stack)
				f.stack[n-2], f.stack[n-1] = f.stack[n-1], f.stack[n-2]
				return nil
			},
			"over": func(f *forth) error {
				if len(f.stack) < 2 {
					return stackError(len(f.stack))
				}
				f.stack = append(f.stack, f.stack[len(f.stack)-2])
				return nil
			},
		},
	}
}

// binOp builds an op that pops two values (a, then b) and pushes the
// result of fn(a, b).
func binOp(fn func(a, b int) (int, error)) op {
	return func(f *forth) error {
		if len(f.stack) < 2 {
			return stackError(len(f.stack))
		}
		a := f.stack[len(f.stack)-2]
		b := f.stack[len(f.stack)-1]
		f.stack = f.stack[:len(f.stack)-2]
		r, err := fn(a, b)
		if err != nil {
			return err
		}
		f.stack = append(f.stack, r)
		return nil
	}
}

func stackError(have int) error {
	if have == 0 {
		return errors.New("empty stack")
	}
	return errors.New("only one value on the stack")
}

// evalLine evaluates one line of input, which may contain word
// definitions and/or executable words.
func (f *forth) evalLine(line string) error {
	tokens := strings.Fields(line)
	for i := 0; i < len(tokens); i++ {
		tok := tokens[i]
		if tok != ":" {
			if err := f.exec(tok); err != nil {
				return err
			}
			continue
		}
		// Definition: ": name body... ;"
		if i+1 >= len(tokens) {
			return errors.New("illegal operation")
		}
		name := strings.ToLower(tokens[i+1])
		if isNumber(name) {
			return errors.New("illegal operation")
		}
		body := tokens[i+2:]
		end := -1
		for j, t := range body {
			if t == ";" {
				end = j
				break
			}
		}
		if end < 0 {
			return errors.New("illegal operation")
		}
		// Compile the body against the word table as it is now, so
		// the definition captures the words in scope at definition
		// time (local scope), then install the new definition.
		def, err := f.compile(body[:end])
		if err != nil {
			return err
		}
		f.words[name] = def
		i += end + 2
	}
	return nil
}

// compile turns a definition body into a single op. Word tokens are
// resolved against the current word table; number tokens become push
// closures.
func (f *forth) compile(body []string) (op, error) {
	ops := make([]op, 0, len(body))
	for _, tok := range body {
		if n, ok := asNumber(tok); ok {
			n := n
			ops = append(ops, func(f *forth) error {
				f.stack = append(f.stack, n)
				return nil
			})
			continue
		}
		word, ok := f.words[strings.ToLower(tok)]
		if !ok {
			return nil, errors.New("undefined operation")
		}
		ops = append(ops, word)
	}
	return func(f *forth) error {
		for _, o := range ops {
			if err := o(f); err != nil {
				return err
			}
		}
		return nil
	}, nil
}

// exec executes a single token: a number is pushed, a word is looked
// up and run.
func (f *forth) exec(tok string) error {
	if n, ok := asNumber(tok); ok {
		f.stack = append(f.stack, n)
		return nil
	}
	word, ok := f.words[strings.ToLower(tok)]
	if !ok {
		return errors.New("undefined operation")
	}
	return word(f)
}

// asNumber reports whether s is a number (an optional leading "-"
// followed by one or more ASCII digits) and returns its value.
func asNumber(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	i := 0
	if s[0] == '-' {
		i = 1
	}
	if i == len(s) {
		return 0, false
	}
	for _, c := range s[i:] {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0, false
	}
	return n, true
}

func isNumber(s string) bool {
	_, ok := asNumber(s)
	return ok
}

